"""Q181：并发聚合查询。Python 3.11+，仅使用标准库。
query 必须是可取消的异步只读接口；同步 SDK 的底层工作无法靠取消协程停止。
整体截止后停止等待业务结果，但资源清理可能额外耗时；接口不得吞掉取消信号。
"""
import asyncio
from dataclasses import dataclass
from typing import Any, Awaitable, Callable


@dataclass(frozen=True)
class Result:
    supplier: str
    status: str
    data: Any = None
    error: str | None = None


async def aggregate(
    queries: dict[str, Callable[[], Awaitable[Any]]],
    *,
    concurrency: int = 5,
    per_timeout: float = 2.0,
    overall_timeout: float = 5.0,
) -> list[Result]:
    if concurrency < 1 or per_timeout <= 0 or overall_timeout <= 0:
        raise ValueError("并发数必须 >= 1，超时必须 > 0")
    if not queries:
        return []
    semaphore = asyncio.Semaphore(concurrency)

    async def run(name, query):
        # 单接口超时从拿到并发槽开始；排队仍计入整体超时。
        async with semaphore:
            try:
                async with asyncio.timeout(per_timeout):
                    return Result(name, "ok", data=await query())
            except TimeoutError:
                return Result(name, "timeout")
            except asyncio.CancelledError:
                raise  # 不吞掉上游取消信号
            except Exception as exc:
                # 对外仅暴露类型，详细异常应写入脱敏内部日志。
                return Result(name, "error", error=type(exc).__name__)

    tasks = {name: asyncio.create_task(run(name, query))
             for name, query in queries.items()}
    try:
        _, pending = await asyncio.wait(
            tasks.values(), timeout=overall_timeout
        )
        for task in pending:
            task.cancel()
        # 等待 finally 等清理完成，避免留下后台任务和未取走的异常。
        await asyncio.gather(*tasks.values(), return_exceptions=True)
        return [
            Result(name, "deadline") if task.cancelled() else task.result()
            for name, task in tasks.items()
        ]
    finally:
        # 客户端断开或调用者取消时，也清理所有子任务。
        for task in tasks.values():
            if not task.done():
                task.cancel()
        await asyncio.gather(*tasks.values(), return_exceptions=True)


async def main():
    async def fast():
        await asyncio.sleep(0.01)
        return [{"hotel_id": "H001", "price_cents": 39900}]

    async def slow():
        await asyncio.sleep(1)
        return []

    print(await aggregate({"A": fast, "B": slow}, overall_timeout=0.05))


if __name__ == "__main__":
    asyncio.run(main())

"""Q183：结构化入住参数校验。Python 3.11+，仅使用标准库。
local_today 必须由服务端按酒店时区计算；房间容量等由可信酒店政策传入。
"""
import re
from datetime import date


def validate_booking(data, *, local_today: date, max_guests_per_room=4,
                     max_rooms=8, max_nights=30):
    if any(type(v) is not int or v < 1 for v in
           (max_guests_per_room, max_rooms, max_nights)):
        raise ValueError("酒店政策参数必须为正整数")
    errors, clean = [], {}

    def error(field, code, message):
        errors.append({"field": field, "code": code, "message": message})

    if not isinstance(data, dict):
        return {"ok": False, "data": None, "errors": [
            {"field": "$", "code": "type", "message": "输入必须为对象"}]}

    for field in ("check_in", "check_out"):
        raw = data.get(field)
        if not isinstance(raw, str) or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", raw):
            error(field, "format", "日期必须是 YYYY-MM-DD")
            continue
        try:
            clean[field] = date.fromisoformat(raw)
        except ValueError:
            error(field, "date", "日期不存在")
    for field, minimum in (("adults", 1), ("children", 0), ("rooms", 1)):
        raw = data.get(field)
        if type(raw) is not int:  # bool 也是 int 的子类，因此不能用 isinstance
            error(field, "type", "必须是整数，不接受布尔值或数字字符串")
        elif raw < minimum:
            error(field, "range", f"必须 >= {minimum}")
        else:
            clean[field] = raw
    if "check_in" in clean and clean["check_in"] < local_today:
        error("check_in", "past_date", "入住日期早于酒店当地今天")
    if "check_in" in clean and "check_out" in clean:
        nights = (clean["check_out"] - clean["check_in"]).days
        if nights <= 0:
            error("check_out", "date_order", "退房必须晚于入住")
        elif nights > max_nights:
            error("check_out", "stay_limit", f"最多入住 {max_nights} 晚")
    if clean.get("rooms", 0) > max_rooms:
        error("rooms", "room_limit", f"单次最多 {max_rooms} 间房")
    if all(k in clean for k in ("adults", "children", "rooms")):
        if clean["adults"] + clean["children"] > clean["rooms"] * max_guests_per_room:
            error("rooms", "capacity", "人数超过当前房型容量，请调整房间数或房型")
    normalized = {k: v.isoformat() if isinstance(v, date) else v
                  for k, v in clean.items()}
    return {"ok": not errors, "data": normalized if not errors else None,
            "errors": errors}


if __name__ == "__main__":
    print(validate_booking({"check_in": "2026-11-01", "check_out": "2026-11-03",
                            "adults": 2, "children": 1, "rooms": 1},
                           local_today=date(2026, 10, 13)))

"""Q186：固定顺序的行程可行性校验。Python 3.11+，标准库。
时间使用相同基准的绝对分钟（生产可由带时区时间戳转换）；不直接比较
不同时区的当地时钟。窗口是 [开放, 关闭]，允许恰好在关闭时结束。
交通回调可根据出发时刻计算交通时间；本题校验给定顺序，不负责全局优化。
"""
from dataclasses import dataclass
from collections.abc import Callable


@dataclass(frozen=True)
class Visit:
    place: str
    duration: int
    windows: tuple[tuple[int, int], ...]
    appointment: int | None = None  # 固定预约开始时刻


def validate_itinerary(visits: list[Visit], *, start_place: str,
                       start_time: int,
                       travel: Callable[[str, str, int], int | None],
                       buffer: int = 0):
    if type(buffer) is not int or buffer < 0:
        raise ValueError("缓冲时间必须为非负整数")
    schedule = []
    place, now = start_place, start_time
    for index, visit in enumerate(visits):
        if type(visit.duration) is not int or visit.duration <= 0:
            raise ValueError("游览时长必须是正整数")
        if any(end < begin for begin, end in visit.windows):
            raise ValueError("时间窗结束不能早于开始")
        duration = travel(place, visit.place, now)
        if duration is None:
            return {"ok": False, "schedule": schedule,
                    "conflict": {"index": index, "place": visit.place,
                                 "reason": "unreachable", "from": place}}
        if type(duration) is not int or duration < 0:
            raise ValueError("交通时间必须是非负整数，或用 None 表示不可达")
        arrival = now + duration + buffer
        choices = []
        for begin, end in visit.windows:
            candidate = max(arrival, begin) if visit.appointment is None else visit.appointment
            if candidate >= arrival and candidate >= begin and candidate + visit.duration <= end:
                choices.append(candidate)
        if not choices:
            return {"ok": False, "schedule": schedule,
                    "conflict": {"index": index, "place": visit.place,
                                 "reason": "no_feasible_window", "arrival": arrival,
                                 "duration": visit.duration, "windows": visit.windows,
                                 "appointment": visit.appointment}}
        begin = min(choices)
        finish = begin + visit.duration
        schedule.append({"place": visit.place, "arrival": arrival,
                         "start": begin, "end": finish, "wait": begin-arrival})
        place, now = visit.place, finish
    return {"ok": True, "schedule": schedule, "conflict": None}


if __name__ == "__main__":
    visits = [Visit("博物馆", 90, ((9*60, 12*60), (13*60, 17*60))),
              Visit("公园", 60, ((8*60, 18*60),))]
    print(validate_itinerary(visits, start_place="酒店", start_time=8*60,
                             travel=lambda a, b, t: 30, buffer=10))

"""Q263：确定性的 DAG 分层规划。Python 3.11+ 标准库。
输入为 {节点名: 前置节点集合}；仅校验依赖并生成层，不执行任务。
"""
def plan_layers(dependencies):
    if not isinstance(dependencies, dict) or any(
        not isinstance(k, str) or not k for k in dependencies
    ):
        raise ValueError("节点必须为非空字符串")
    nodes = set(dependencies)
    deps = {}
    for node, parents in dependencies.items():
        if not isinstance(parents, (list, tuple, set, frozenset)) or any(
            not isinstance(p, str) for p in parents
        ):
            raise ValueError("依赖必须为字符串序列或集合")
        deps[node] = set(parents)
        if node in deps[node]:
            raise ValueError(f"自依赖：{node}")
        unknown = deps[node] - nodes
        if unknown:
            raise ValueError(f"未知依赖：{sorted(unknown)}")
    children = {node: set() for node in nodes}
    indegree = {node: len(parents) for node, parents in deps.items()}
    for node, parents in deps.items():
        for parent in parents:
            children[parent].add(node)
    ready = sorted(node for node in nodes if indegree[node] == 0)
    layers, seen = [], set()
    while ready:
        layers.append(ready)
        next_ready = []
        for node in ready:
            seen.add(node)
            for child in children[node]:
                indegree[child] -= 1
                if indegree[child] == 0:
                    next_ready.append(child)
        ready = sorted(next_ready)
    if len(seen) != len(nodes):
        # 残余集合包括环及被环阻塞的下游，不声称全部都属于环。
        raise ValueError(f"依赖存在环；未能调度的节点：{sorted(nodes-seen)}")
    return layers


if __name__ == "__main__":
    print(plan_layers({"需求": [], "酒店": ["需求"], "航班": ["需求"],
                       "报价": ["酒店", "航班"]}))

"""Q264：单订单、连续序号事件投影。Python 3.11+ 标准库。
上游序号从 1 起且对该订单连续；状态事件已鉴权。线程安全内存示例。
非法迁移整次提交回滚。生产需在数据库事务中持久化历史、水位与缓冲，
并制定缺口超时、历史保留和人工冲突处理策略。
"""
from dataclasses import dataclass
from threading import Lock


@dataclass(frozen=True)
class Event:
    seq: int
    state: str


class Projection:
    ALLOWED = {"NEW": {"PENDING"}, "PENDING": {"CONFIRMED", "FAILED"},
               "CONFIRMED": {"CANCELLED"}, "FAILED": set(), "CANCELLED": set()}

    def __init__(self, max_pending=100):
        if type(max_pending) is not int or max_pending < 1:
            raise ValueError("max_pending 必须为正整数")
        self.max_pending = max_pending
        self.state, self.version = "NEW", 0
        self.pending, self.history = {}, {}
        self.lock = Lock()

    def submit(self, event):
        if not isinstance(event, Event) or type(event.seq) is not int or event.seq < 1:
            raise ValueError("事件序号必须为正整数")
        if event.state not in self.ALLOWED:
            raise ValueError("未知订单状态")
        with self.lock:
            previous = self.history.get(event.seq) or self.pending.get(event.seq)
            if previous is not None:
                if previous != event:
                    raise ValueError("同序号内容冲突")
                return self.state, self.version
            pending = self.pending | {event.seq: event}
            state, version = self.state, self.version
            applied = {}
            while version + 1 in pending:
                current = pending.pop(version + 1)
                if current.state not in self.ALLOWED[state]:
                    raise ValueError(f"非法迁移：{state} -> {current.state}")
                state, version = current.state, current.seq
                applied[version] = current
            if len(pending) > self.max_pending:
                raise ValueError("乱序缓冲已满，请查证缺失事件")
            # 全部验证通过后才提交，避免部分应用后的错误状态。
            self.state, self.version, self.pending = state, version, pending
            self.history.update(applied)
            return state, version


if __name__ == "__main__":
    order = Projection()
    print(order.submit(Event(2, "CONFIRMED")))
    print(order.submit(Event(1, "PENDING")))

"""Q265：固定两位小数币种的报价示例。Python 3.11+ 标准库。
演示口径：房费=单价*间夜数；税费按总房费乘税率后四舍五入到分；
优惠为固定金额。真实税费、币种和退款规则必须由业务契约另行确定。
"""
import re
from decimal import Decimal, ROUND_HALF_UP, localcontext


def parse_decimal(text, *, places, upper):
    if not isinstance(text, str) or not re.fullmatch(
        rf"\d{{1,9}}(?:\.\d{{1,{places}}})?", text
    ):
        raise ValueError("只接受非负、有限且精度受限的十进制字符串")
    value = Decimal(text)
    if value > upper:
        raise ValueError("数值超出允许范围")
    return value


def quote(unit_price, nights, tax_rate="0", discount="0"):
    if type(nights) is not int or not 1 <= nights <= 365:
        raise ValueError("间夜数必须为 1 到 365 的整数")
    price = parse_decimal(unit_price, places=2, upper=Decimal("1000000"))
    rate = parse_decimal(tax_rate, places=6, upper=Decimal("1"))
    reduction = parse_decimal(discount, places=2, upper=Decimal("1000000"))
    with localcontext() as context:
        context.prec = 32
        cent = Decimal("0.01")
        room = (price * nights).quantize(cent, rounding=ROUND_HALF_UP)
        tax = (room * rate).quantize(cent, rounding=ROUND_HALF_UP)
        if reduction > room + tax:
            raise ValueError("优惠不能超过应付金额")
        total = (room + tax - reduction).quantize(cent, rounding=ROUND_HALF_UP)
        return {"room": format(room, ".2f"), "tax": format(tax, ".2f"),
                "discount": format(reduction, ".2f"), "total": format(total, ".2f")}


if __name__ == "__main__":
    print(quote("399.99", 2, tax_rate="0.06", discount="50.00"))

"""Q266：RRF 检索融合。Python 3.11+ 标准库。
输入是多个已排序的文档 ID 列表。先去除各路内部重复并压紧排名，
使用 Fraction 精确累加以保证路顺序变化不影响得分；输出同分按 ID 排序。
生产入口应先按租户和权限过滤候选，并限制输入规模。
"""
from fractions import Fraction


def rrf(rankings, *, k=60, top_k=10):
    if type(k) is not int or k < 0 or type(top_k) is not int or top_k < 0:
        raise ValueError("k 和 top_k 必须为非负整数")
    scores = {}
    for ranking in rankings:
        seen, rank = set(), 0
        for doc_id in ranking:
            if not isinstance(doc_id, str) or not doc_id:
                raise ValueError("文档 ID 必须是非空字符串")
            if doc_id in seen:
                continue
            seen.add(doc_id)
            rank += 1
            scores[doc_id] = scores.get(doc_id, Fraction(0)) + Fraction(1, k + rank)
    ordered = sorted(scores.items(), key=lambda item: (-item[1], item[0]))
    return [(doc, float(score)) for doc, score in ordered[:top_k]]


if __name__ == "__main__":
    print(rrf([["酒店A", "酒店B", "酒店B"], ["酒店B", "酒店C"]]))
